// Lago REST client. Server-side only: it holds the secret API key.
// Kept free of app imports so it can be tested directly with `node --test`.
import { createHmac, timingSafeEqual, verify } from "node:crypto";

export type LagoConfig = { apiUrl: string; apiKey: string; timeoutMs?: number; maxRetries?: number };

export class LagoError extends Error {
  status: number;
  body: unknown;
  constructor(status: number, body: unknown) {
    super(`Lago API error ${status}`);
    this.status = status;
    this.body = body;
  }
}

// LAGO_API_URL is the API origin (US Cloud, EU Cloud, or self-hosted), without /api/v1.
export function configFromEnv(env: Record<string, string | undefined> = process.env): LagoConfig {
  const apiUrl = env.LAGO_API_URL;
  const apiKey = env.LAGO_API_KEY;
  if (!apiUrl || !apiKey) throw new Error("LAGO_API_URL and LAGO_API_KEY are required");
  return { apiUrl: apiUrl.replace(/\/+$/, "").replace(/\/api\/v1$/, ""), apiKey };
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
const backoff = (attempt: number) => Math.min(8_000, 250 * 2 ** attempt) * Math.random();

// Retries only network errors, timeouts, 429 and 5xx, with bounded jittered backoff.
async function lago(config: LagoConfig, method: string, path: string, body?: unknown): Promise<any> {
  const attempts = (config.maxRetries ?? 4) + 1;
  for (let attempt = 1; ; attempt++) {
    let response: Response;
    try {
      response = await fetch(`${config.apiUrl}/api/v1${path}`, {
        method,
        headers: { Authorization: `Bearer ${config.apiKey}`, "Content-Type": "application/json" },
        body: body === undefined ? undefined : JSON.stringify(body),
        signal: AbortSignal.timeout(config.timeoutMs ?? 10_000),
      });
    } catch (error) {
      if (attempt >= attempts) throw error;
      await sleep(backoff(attempt));
      continue;
    }
    const text = await response.text();
    let json: unknown = null;
    try {
      json = text ? JSON.parse(text) : null;
    } catch {
      json = text; // e.g. an HTML 502 page from a proxy
    }
    if (response.ok) return json;
    const transient = response.status === 429 || response.status >= 500;
    if (!transient || attempt >= attempts) throw new LagoError(response.status, json);
    await sleep(backoff(attempt));
  }
}

// Upsert: Lago updates the customer when external_id already exists.
export function upsertCustomer(config: LagoConfig, account: { id: string; name: string; email?: string; currency: string }) {
  return lago(config, "POST", "/customers", {
    customer: { external_id: account.id, name: account.name, email: account.email, currency: account.currency },
  });
}

// external_id is the subscription's own durable ID, never the customer ID.
export function createSubscription(config: LagoConfig, s: { id: string; customerId: string; planCode: string }) {
  return lago(config, "POST", "/subscriptions", {
    subscription: { external_id: s.id, external_customer_id: s.customerId, plan_code: s.planCode },
  });
}

export type UsageEvent = {
  id: string; // durable source record ID, reused on every retry
  subscriptionId: string;
  metricCode: string;
  occurredAt: Date; // stored with the record, reused on every retry
  properties: Record<string, string | number>;
};

export function toLagoEvent(event: UsageEvent) {
  return {
    transaction_id: event.id,
    external_subscription_id: event.subscriptionId,
    code: event.metricCode,
    timestamp: (event.occurredAt.getTime() / 1000).toFixed(3),
    properties: event.properties,
  };
}

// "duplicate" means Lago already holds an event with this transaction_id. It is not a
// plain success: the caller must reconcile it against the stored event before trusting it.
export async function sendUsage(config: LagoConfig, event: UsageEvent): Promise<"accepted" | "duplicate"> {
  try {
    await lago(config, "POST", "/events", { event: toLagoEvent(event) });
    return "accepted";
  } catch (error) {
    if (isDuplicateEventError(error)) return "duplicate";
    throw error;
  }
}

export function isDuplicateEventError(error: unknown): boolean {
  if (!(error instanceof LagoError) || error.status !== 422) return false;
  const details = (error.body as any)?.error_details;
  return Array.isArray(details?.transaction_id) && details.transaction_id.includes("value_already_exist");
}

export function isRetryable(error: unknown): boolean {
  if (!(error instanceof LagoError)) return true; // network error or timeout
  return error.status === 429 || error.status >= 500;
}

export async function currentUsage(config: LagoConfig, customerId: string, subscriptionId: string) {
  const query = new URLSearchParams({ external_subscription_id: subscriptionId });
  const { customer_usage } = await lago(config, "GET", `/customers/${encodeURIComponent(customerId)}/current_usage?${query}`);
  return customer_usage as {
    amount_cents: number;
    currency: string;
    charges_usage: { units: string; amount_cents: number; billable_metric: { code: string } }[];
  };
}

// The JWT public key is a base64-encoded PEM. Fetch it once and cache it.
export async function webhookPublicKey(config: LagoConfig): Promise<string> {
  const { webhook } = await lago(config, "GET", "/webhooks/json_public_key");
  return Buffer.from(webhook.public_key, "base64").toString("utf8");
}

export type WebhookKeys = { issuer: string; publicKeyPem?: string; hmacKey?: string };

// rawBody must be the exact request bytes. Never re-serialize parsed JSON.
export function verifyWebhook(rawBody: string, headers: Headers, keys: WebhookKeys): any {
  const signature = headers.get("x-lago-signature") ?? "";
  const algorithm = headers.get("x-lago-signature-algorithm");
  if (algorithm === "jwt" && keys.publicKeyPem) {
    const [header, payload, sig] = signature.split(".");
    if (!header || !payload || !sig) throw new Error("malformed webhook JWT");
    if (JSON.parse(Buffer.from(header, "base64url").toString()).alg !== "RS256") throw new Error("unexpected JWT algorithm");
    const valid = verify("RSA-SHA256", Buffer.from(`${header}.${payload}`), keys.publicKeyPem, Buffer.from(sig, "base64url"));
    const claims = JSON.parse(Buffer.from(payload, "base64url").toString());
    if (!valid || claims.iss !== keys.issuer || claims.data !== rawBody) throw new Error("invalid webhook signature");
  } else if (algorithm === "hmac" && keys.hmacKey) {
    const expected = createHmac("sha256", keys.hmacKey).update(rawBody).digest();
    const received = Buffer.from(signature, "base64");
    if (received.length !== expected.length || !timingSafeEqual(received, expected)) throw new Error("invalid webhook signature");
  } else {
    throw new Error("unsupported or unconfigured webhook signature algorithm");
  }
  return JSON.parse(rawBody);
}

// Stand-in for the app's database.
export type Workspace = { id: string; name: string; email: string; plan: "free" | "pro" };
export type Generation = { id: string; workspaceId: string; model: string; inputTokens: number; outputTokens: number; createdAt: Date };
// Links a workspace (Lago customer) to its own Lago subscription. Keyed by workspaceId.
export type BillingEnrollment = { subscriptionId: string; workspaceId: string; planCode: string; status: "active" | "terminated"; createdAt: Date };
// Delivery state of a generation's usage event, kept apart from the generation itself. Keyed by generationId.
export type UsageDelivery = {
  generationId: string;
  status: "pending" | "delivered" | "needs_reconciliation" | "failed";
  attempts: number;
  lastError?: string;
  updatedAt: Date;
};
// Lago webhooks, keyed by X-Lago-Unique-Key (the key must be unique in a real table).
export type WebhookInboxEntry = { uniqueKey: string; type: string; payload: unknown; receivedAt: Date; processedAt?: Date };
export const db = {
  workspaces: new Map<string, Workspace>(),
  generations: new Map<string, Generation>(),
  billingEnrollments: new Map<string, BillingEnrollment>(),
  usageDeliveries: new Map<string, UsageDelivery>(),
  webhookInbox: new Map<string, WebhookInboxEntry>(),
};

// Billing adapter: turns app records into Lago customers, subscriptions and usage events.
// Lago owns metering, pricing and invoices; the app owns identity, usage records and delivery state.
import type { BillingEnrollment, Generation, UsageDelivery, Workspace } from "../db";
import { createSubscription, isRetryable, sendUsage, upsertCustomer, type LagoConfig, type UsageEvent } from "./lago.ts";

export const METRIC_CODE = "llm_tokens"; // sum_agg on properties.tokens, recurring: false
export const PRO_PLAN_CODE = "pro"; // $49/month in advance + $0.02 per 1,000 tokens in arrears
export const MAX_DELIVERY_ATTEMPTS = 10;

export type BillingStore = {
  billingEnrollments: Map<string, BillingEnrollment>;
  usageDeliveries: Map<string, UsageDelivery>;
};

export type BillingDeps = { store: BillingStore; config: () => LagoConfig; log?: (msg: string, fields: Record<string, unknown>) => void };

// Every field derives from the stored generation, so a retry sends an identical event.
export function generationUsageEvent(generation: Generation, subscriptionId: string): UsageEvent {
  return {
    id: generation.id,
    subscriptionId,
    metricCode: METRIC_CODE,
    occurredAt: generation.createdAt,
    properties: {
      tokens: generation.inputTokens + generation.outputTokens,
      input_tokens: generation.inputTokens,
      output_tokens: generation.outputTokens,
      model: generation.model,
    },
  };
}

export function validateUsageEvent(event: UsageEvent): void {
  for (const key of ["tokens", "input_tokens", "output_tokens"]) {
    const value = event.properties[key];
    if (typeof value !== "number" || !Number.isFinite(value) || value < 0 || !Number.isInteger(value)) {
      throw new Error(`invalid usage property ${key}`);
    }
  }
  if (!event.id || !event.subscriptionId) throw new Error("usage event requires id and subscriptionId");
  if (Number.isNaN(event.occurredAt.getTime()) || event.occurredAt.getTime() < 0) throw new Error("invalid usage timestamp");
}

// Creates the Lago customer and Pro subscription for a workspace. The subscription ID is
// persisted before calling Lago so a retry reuses it instead of creating a second subscription.
export async function enrollWorkspace(deps: BillingDeps, workspace: Workspace, planCode = PRO_PLAN_CODE): Promise<BillingEnrollment> {
  const { store } = deps;
  let enrollment = store.billingEnrollments.get(workspace.id);
  if (enrollment?.status === "active") return enrollment;
  if (!enrollment || enrollment.status === "terminated") {
    enrollment = { subscriptionId: `sub_${crypto.randomUUID()}`, workspaceId: workspace.id, planCode, status: "pending", createdAt: new Date() };
    store.billingEnrollments.set(workspace.id, enrollment);
  }
  const config = deps.config();
  await upsertCustomer(config, { id: workspace.id, name: workspace.name, email: workspace.email, currency: "USD" });
  await createSubscription(config, { id: enrollment.subscriptionId, customerId: workspace.id, planCode: enrollment.planCode });
  enrollment = { ...enrollment, status: "active", activatedAt: new Date() };
  store.billingEnrollments.set(workspace.id, enrollment);
  return enrollment;
}

// Usage only bills against an active subscription, and only for work done after activation.
function billableSubscription(store: BillingStore, generation: Generation): string | undefined {
  const enrollment = store.billingEnrollments.get(generation.workspaceId);
  if (enrollment?.status !== "active" || !enrollment.activatedAt) return undefined;
  if (generation.createdAt < enrollment.activatedAt) return undefined;
  return enrollment.subscriptionId;
}

export type DeliveryOutcome = "not_billable" | UsageDelivery["status"];

export async function deliverGenerationUsage(deps: BillingDeps, generation: Generation): Promise<DeliveryOutcome> {
  const { store } = deps;
  const subscriptionId = billableSubscription(store, generation);
  if (!subscriptionId) return "not_billable";

  const previous = store.usageDeliveries.get(generation.id);
  if (previous && previous.status !== "pending") return previous.status;
  const attempts = (previous?.attempts ?? 0) + 1;
  const record = (status: UsageDelivery["status"], lastError?: string) => {
    store.usageDeliveries.set(generation.id, { generationId: generation.id, status, attempts, lastError, updatedAt: new Date() });
    deps.log?.("lago usage delivery", { generationId: generation.id, subscriptionId, status, attempts, error: lastError });
    return status;
  };
  // Persist intent first so a crash mid-send leaves a pending record for replay.
  record("pending");

  try {
    const event = generationUsageEvent(generation, subscriptionId);
    validateUsageEvent(event);
    const result = await sendUsage(deps.config(), event);
    // A duplicate is not proof this exact usage was billed: compare the stored Lago event
    // (subscription, timestamp, properties) with the generation before marking it delivered.
    return record(result === "accepted" ? "delivered" : "needs_reconciliation");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const retry = isRetryable(error) && attempts < MAX_DELIVERY_ATTEMPTS;
    return record(retry ? "pending" : "failed", message);
  }
}

// Replays pending deliveries with their original IDs and timestamps. Run from a scheduled job.
export async function deliverPendingUsage(deps: BillingDeps, generations: Map<string, Generation>): Promise<Record<string, number>> {
  const counts: Record<string, number> = {};
  for (const delivery of [...deps.store.usageDeliveries.values()]) {
    if (delivery.status !== "pending") continue;
    const generation = generations.get(delivery.generationId);
    if (!generation) continue;
    const outcome = await deliverGenerationUsage(deps, generation);
    counts[outcome] = (counts[outcome] ?? 0) + 1;
  }
  return counts;
}

