// Lago webhook intake: verify the raw body, store once per X-Lago-Unique-Key, then process asynchronously.
import type { BillingEnrollment, WebhookInboxEntry } from "../db";
import { verifyWebhook, type WebhookKeys } from "./lago.ts";

export type WebhookStore = {
  webhookInbox: Map<string, WebhookInboxEntry>;
  billingEnrollments: Map<string, BillingEnrollment>;
};

export type WebhookDeps = {
  store: WebhookStore;
  keys: () => Promise<WebhookKeys>;
  enqueue: (uniqueKey: string) => void;
};

export function makeWebhookHandler(deps: WebhookDeps) {
  return async function POST(request: Request): Promise<Response> {
    const rawBody = await request.text();
    let payload: any;
    try {
      payload = verifyWebhook(rawBody, request.headers, await deps.keys());
    } catch {
      return new Response("invalid signature", { status: 401 });
    }
    const uniqueKey = request.headers.get("x-lago-unique-key");
    if (!uniqueKey) return new Response("missing unique key", { status: 400 });
    // With a real database, this is an INSERT guarded by a unique constraint on unique_key.
    if (!deps.store.webhookInbox.has(uniqueKey)) {
      deps.store.webhookInbox.set(uniqueKey, { uniqueKey, type: String(payload?.webhook_type ?? "unknown"), payload, receivedAt: new Date() });
      deps.enqueue(uniqueKey);
    }
    return new Response(null, { status: 204 }); // only after durable storage
  };
}

// Idempotent: safe to run more than once for the same inbox entry.
export function processWebhook(store: WebhookStore, uniqueKey: string): void {
  const entry = store.webhookInbox.get(uniqueKey);
  if (!entry || entry.processedAt) return;
  const payload = entry.payload as any;
  if (entry.type === "subscription.terminated") {
    const externalId = payload?.subscription?.external_id;
    for (const [workspaceId, enrollment] of store.billingEnrollments) {
      if (enrollment.subscriptionId === externalId) store.billingEnrollments.set(workspaceId, { ...enrollment, status: "terminated" });
    }
  }
  // Add handlers here (e.g. invoice.created, invoice.payment_failure) as product needs arise.
  store.webhookInbox.set(uniqueKey, { ...entry, processedAt: new Date() });
}

