import { after } from "next/server";
import { db } from "@/lib/db";
import { summarize } from "@/lib/llm";
import { billingDeps } from "@/lib/billing";
import { deliverGenerationUsage } from "@/lib/billing/usage.ts";

export async function POST(request: Request) {
  const { workspaceId, text } = await request.json();
  const result = await summarize(text);
  const generation = {
    id: crypto.randomUUID(),
    workspaceId,
    model: result.model,
    inputTokens: result.usage.input_tokens,
    outputTokens: result.usage.output_tokens,
    createdAt: new Date(),
  };
  db.generations.set(generation.id, generation);
  // The stored generation is the durable usage record; send it to Lago after responding.
  // Failures stay pending and are replayed by deliverPendingUsage.
  after(() => deliverGenerationUsage(billingDeps, generation));
  return Response.json({ summary: result.summary });
}

import { db } from "@/lib/db";
