// Offline tests for the Lago billing adapter. Run: npm test (Node 24 strips TS types natively).
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { createHmac, generateKeyPairSync, sign } from "node:crypto";
import type { BillingEnrollment, Generation, UsageDelivery, WebhookInboxEntry } from "../lib/db";
import { configFromEnv, type LagoConfig } from "../lib/billing/lago.ts";
import { deliverGenerationUsage, deliverPendingUsage, enrollWorkspace, generationUsageEvent, type BillingDeps } from "../lib/billing/usage.ts";
import { makeWebhookHandler, processWebhook } from "../lib/billing/webhooks.ts";

const config: LagoConfig = { apiUrl: "https://lago.test", apiKey: "test_key", maxRetries: 2, timeoutMs: 1_000 };
type Call = { method: string; url: string; body: any };
let calls: Call[];
let responses: Array<() => Response>;
let store: { billingEnrollments: Map<string, BillingEnrollment>; usageDeliveries: Map<string, UsageDelivery>; webhookInbox: Map<string, WebhookInboxEntry> };
let deps: BillingDeps;

const json = (status: number, body: unknown) => () => new Response(JSON.stringify(body), { status });

beforeEach(() => {
  calls = [];
  responses = [];
  globalThis.fetch = (async (url: string, init: RequestInit) => {
    calls.push({ method: init.method!, url, body: init.body ? JSON.parse(init.body as string) : undefined });
    const next = responses.shift();
    if (!next) throw new Error("unexpected fetch");
    return next();
  }) as typeof fetch;
  store = { billingEnrollments: new Map(), usageDeliveries: new Map(), webhookInbox: new Map() };
  deps = { store, config: () => config };
});

const activatedAt = new Date("2026-10-01T00:00:00.000Z");
function enroll(workspaceId = "ws_1") {
  store.billingEnrollments.set(workspaceId, { subscriptionId: "sub_1", workspaceId, planCode: "pro", status: "active", createdAt: activatedAt, activatedAt });
}
function generation(overrides: Partial<Generation> = {}): Generation {
  return { id: "gen_1", workspaceId: "ws_1", model: "gpt-4.1-mini", inputTokens: 900, outputTokens: 100, createdAt: new Date("2026-10-05T12:00:00.123Z"), ...overrides };
}

test("config strips trailing slash and /api/v1 so the path is not doubled", () => {
  assert.equal(configFromEnv({ LAGO_API_URL: "https://api.getlago.com/api/v1/", LAGO_API_KEY: "k" }).apiUrl, "https://api.getlago.com");
  assert.throws(() => configFromEnv({}));
});

test("usage event derives id and timestamp from the stored generation", () => {
  const event = generationUsageEvent(generation(), "sub_1");
  assert.equal(event.id, "gen_1");
  assert.equal(event.metricCode, "llm_tokens");
  assert.equal(event.properties.tokens, 1000);
  assert.equal(event.occurredAt.toISOString(), "2026-10-05T12:00:00.123Z");
});

test("retries a 503 with the identical event body, then marks delivered", async () => {
  enroll();
  responses.push(json(503, {}), json(200, { event: {} }));
  assert.equal(await deliverGenerationUsage(deps, generation()), "delivered");
  assert.equal(calls.length, 2);
  assert.deepEqual(calls[0].body, calls[1].body);
  assert.deepEqual(calls[0].body.event, {
    transaction_id: "gen_1",
    external_subscription_id: "sub_1",
    code: "llm_tokens",
    timestamp: "1791201600.123",
    properties: { tokens: 1000, input_tokens: 900, output_tokens: 100, model: "gpt-4.1-mini" },
  });
  // Already delivered: a second call does not resend.
  assert.equal(await deliverGenerationUsage(deps, generation()), "delivered");
  assert.equal(calls.length, 2);
});

test("duplicate transaction_id is flagged for reconciliation, not treated as success", async () => {
  enroll();
  responses.push(json(422, { status: 422, error: "Unprocessable Entity", code: "validation_errors", error_details: { transaction_id: ["value_already_exist"] } }));
  assert.equal(await deliverGenerationUsage(deps, generation()), "needs_reconciliation");
});

test("other 422s are contract errors: failed without retry", async () => {
  enroll();
  responses.push(json(422, { error_details: { code: ["metric_not_found"] } }));
  assert.equal(await deliverGenerationUsage(deps, generation()), "failed");
  assert.equal(calls.length, 1);
});

test("exhausted transient failures stay pending and replay with the same id and timestamp", async () => {
  enroll();
  responses.push(json(500, {}), json(500, {}), json(500, {}));
  assert.equal(await deliverGenerationUsage(deps, generation()), "pending");
  responses.push(json(200, {}));
  assert.deepEqual(await deliverPendingUsage(deps, new Map([["gen_1", generation()]])), { delivered: 1 });
  assert.deepEqual(calls.at(-1)!.body, calls[0].body);
});

test("no event is sent without an active subscription or for work before activation", async () => {
  assert.equal(await deliverGenerationUsage(deps, generation()), "not_billable");
  enroll();
  assert.equal(await deliverGenerationUsage(deps, generation({ createdAt: new Date("2026-09-30T23:59:59Z") })), "not_billable");
  assert.equal(calls.length, 0);
});

test("enrollment keeps separate customer and subscription IDs and reuses the subscription ID on retry", async () => {
  const workspace = { id: "ws_1", name: "Acme", email: "billing@example.com", plan: "pro" as const };
  responses.push(json(200, {}), json(422, { error_details: { plan_code: ["plan_not_found"] } }));
  await assert.rejects(enrollWorkspace(deps, workspace));
  const pending = store.billingEnrollments.get("ws_1")!;
  assert.equal(pending.status, "pending");
  responses.push(json(200, {}), json(200, {}));
  const active = await enrollWorkspace(deps, workspace);
  assert.equal(active.status, "active");
  assert.equal(active.subscriptionId, pending.subscriptionId);
  assert.equal(calls[3].body.subscription.external_id, pending.subscriptionId);
  assert.equal(calls[3].body.subscription.external_customer_id, "ws_1");
  assert.notEqual(active.subscriptionId, "ws_1");
});

test("money: 120,000 tokens on Pro = $49.00 + $2.40 = $51.40", () => {
  // Independent expectation from the plan: 4900 cents fee, standard charge 0.00002 USD/token.
  const events = [40_000, 50_000, 30_000].map((tokens, i) =>
    generationUsageEvent(generation({ id: `gen_${i}`, inputTokens: tokens - 1_000, outputTokens: 1_000 }), "sub_1"),
  );
  const tokens = events.reduce((sum, e) => sum + Number(e.properties.tokens), 0);
  assert.equal(tokens, 120_000);
  const usageCents = (tokens * 2) / 1_000; // $0.02 per 1,000 tokens = 2 cents per 1,000
  assert.equal(usageCents, 240);
  assert.equal(4_900 + usageCents, 5_140);
});

const hmacKey = "whsec_test";
function webhookRequest(body: string, headers: Record<string, string>) {
  return new Request("https://app.test/api/lago/webhooks", { method: "POST", body, headers });
}
function hmacHeaders(body: string, uniqueKey = "uk_1") {
  return { "x-lago-signature": createHmac("sha256", hmacKey).update(body).digest("base64"), "x-lago-signature-algorithm": "hmac", "x-lago-unique-key": uniqueKey };
}

test("webhook: valid HMAC stored once per unique key, tampered body rejected", async () => {
  const enqueued: string[] = [];
  const handler = makeWebhookHandler({ store, keys: async () => ({ issuer: config.apiUrl, hmacKey }), enqueue: (k) => enqueued.push(k) });
  const body = JSON.stringify({ webhook_type: "subscription.terminated", subscription: { external_id: "sub_1" } });
  assert.equal((await handler(webhookRequest(body, hmacHeaders(body)))).status, 204);
  assert.equal((await handler(webhookRequest(body, hmacHeaders(body)))).status, 204);
  assert.deepEqual(enqueued, ["uk_1"]);
  const tampered = body.replace("sub_1", "sub_2");
  assert.equal((await handler(webhookRequest(tampered, hmacHeaders(body, "uk_2")))).status, 401);
  assert.equal(store.webhookInbox.size, 1);

  enroll();
  processWebhook(store, "uk_1");
  processWebhook(store, "uk_1");
  assert.equal(store.billingEnrollments.get("ws_1")!.status, "terminated");
  assert.ok(store.webhookInbox.get("uk_1")!.processedAt);
});

test("webhook: RS256 JWT verified against raw body and issuer", async () => {
  const { privateKey, publicKey } = generateKeyPairSync("rsa", { modulusLength: 2048 });
  const publicKeyPem = publicKey.export({ type: "spki", format: "pem" }).toString();
  const handler = makeWebhookHandler({ store, keys: async () => ({ issuer: config.apiUrl, publicKeyPem }), enqueue: () => {} });
  const body = JSON.stringify({ webhook_type: "invoice.created" });
  const jwt = (data: string, iss = config.apiUrl) => {
    const h = Buffer.from(JSON.stringify({ alg: "RS256" })).toString("base64url");
    const p = Buffer.from(JSON.stringify({ data, iss })).toString("base64url");
    return `${h}.${p}.${sign("RSA-SHA256", Buffer.from(`${h}.${p}`), privateKey).toString("base64url")}`;
  };
  const headers = (sig: string) => ({ "x-lago-signature": sig, "x-lago-signature-algorithm": "jwt", "x-lago-unique-key": "uk_jwt" });
  assert.equal((await handler(webhookRequest(body, headers(jwt(body))))).status, 204);
  assert.equal((await handler(webhookRequest(body + " ", headers(jwt(body))))).status, 401);
  assert.equal((await handler(webhookRequest(body, headers(jwt(body, "https://evil.test"))))).status, 401);
});

